import math

def largest_lovely(n):
    """Find the largest lovely divisor of n."""

    # Find prime factors
    prime_factors = set()

    # Check for divisibility by 2
    if n % 2 == 0:
        prime_factors.add(2)
        while n % 2 == 0:
            n //= 2

    # Check for odd divisors up to sqrt(n)
    i = 3
    while i <= math.isqrt(n) + 1:
        if n % i == 0:
            prime_factors.add(i)
            while n % i == 0:
                n //= i
        i += 2

    # If n is still > 1, it's a prime factor
    if n > 1:
        prime_factors.add(n)

    # Calculate the product of prime factors
    result = 1
    for p in prime_factors:
        result *= p

    return result

n = int(input())
print(largest_lovely(n))
