def is_valid(grid, n, m):
    # Build bipartite graph
    graph = [set() for _ in range(n + m)]  # Rows 0..n-1, Columns n..n+m-1
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                graph[i].add(n + j)
                graph[n + j].add(i)

    # Find connected components using BFS
    visited = [False] * (n + m)
    components = []

    for node in range(n + m):
        if not visited[node]:
            # BFS to find all nodes in this component
            queue = [node]
            visited[node] = True
            component = [node]

            while queue:
                current = queue.pop(0)
                for neighbor in graph[current]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        component.append(neighbor)
                        queue.append(neighbor)

            components.append(component)

    # Check if each component is a biclique
    for component in components:
        # Separate rows and columns
        rows = [i for i in component if i < n]
        cols = [i for i in component if i >= n]

        # Check if every row connects to every column
        for r in rows:
            for c in cols:
                if c not in graph[r]:
                    return False

    return True

n, m = map(int, input().split())
grid = []
for _ in range(n):
    grid.append(input().strip())

if is_valid(grid, n, m):
    print("Yes")
else:
    print("No")
