    it = iter(input)

    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        W = int(next(it))
        weights = []

        for i in range(n):
            weights.append((int(next(it)), i + 1))  # store (weight, index)

        # Sort by weight descending
        weights.sort(reverse=True, key=lambda x: x[0])

        total = 0
        selected = []

        for weight, idx in weights:
            if total + weight > W:
                # This item is too heavy to add to the current total
                # So skip it and try to add smaller items later
                continue
            else:
                # Try to add this item
                # First check if we need to remove items to make space
                # We'll remove items until we can add this one
                while total + weight > W:
                    if selected:
                        # Remove the smallest item
                        min_idx = min(range(len(selected)), key=lambda i: weights[selected[i]][0])
                        total -= weights[selected[min_idx]][0]
                        selected.pop(min_idx)
                    else:
                        break  # shouldn't happen

                if total + weight <= W:
                    total += weight
                    selected.append(idx)
                else:
                    # Still can't add
                    pass

        # After processing all items, check if we have a valid solution
        if selected:
            # Check if total is at least W/2
            if total >= W / 2:
                print(len(selected))
                print(' '.join(map(str, selected)))
            else:
                print(-1)
        else:
            print(-1)

