def is_beautiful(counts, k):
    """Check if counts of each character are divisible by k"""
    for c in counts.values():
        if c % k != 0:
            return False
    return True

def solve(n, k, s):
    # Count characters in s
    counts = {}
    for c in s:
        counts[c] = counts.get(c, 0) + 1

    # Check if s is already beautiful
    if is_beautiful(counts, k):
        return s

    # Try to find the next beautiful string
    for i in range(n):
        current_char = s[i]

        # Try each character greater than current_char
        for c in range(ord(current_char) + 1, ord('z') + 1):
            next_char = chr(c)

            # Set position i to next_char
            new_s = s[:i] + next_char + s[i+1:]

            # Count characters used so far
            used = {}
            for j in range(n):
                used[s[j]] = used.get(s[j], 0) + 1
            used[next_char] = used.get(next_char, 0) + 1

            # Fill the rest of the string with the smallest possible beautiful string
            # Start from position i+1
            remaining_positions = n - i - 1

            # We need to fill remaining_positions with characters such that:
            # - Each character's count is divisible by k
            # - We use the lexicographically smallest characters possible
            # - The total length is remaining_positions

            # Let's try to fill with the smallest possible characters
            for j in range(i+1, n):
                for c2 in range(ord('a'), ord('z') + 1):
                    c2_char = chr(c2)

                    # Check if we can add c2_char
                    # Counts after adding: current counts + 1 for c2_char
                    temp_counts = used.copy()
                    temp_counts[c2_char] = temp_counts.get(c2_char, 0) + 1

                    if is_beautiful(temp_counts, k):
                        # Can add this character
                        used[c2_char] = used.get(c2_char, 0) + 1
                        new_s = new_s[:j] + c2_char + new_s[j+1:]
                        break
                else:
                    # No character can be added; this path doesn't work
                    break
            else:
                # Successfully filled the rest
                return new_s

    return -1

def main():
    T = int(input())
    for _ in range(T):
        n, k = map(int, input().split())
        s = input().strip()

        result = solve(n, k, s)
        print(result)

if __name__ == "__main__":
    main()
"}

