    # Check leading coefficients
    if f1[-1] != 1 or f2[-1] != 1:
        print(-1)
        return

    # Check degrees
    deg1 = len(f1) - 1
    deg2 = len(f2) - 1
    if deg1 <= deg2 or deg1 > n or deg2 > n:
        print(-1)
        return

    # Check if Euclid's algorithm takes exactly n steps
    steps = 0
    a, b = f1, f2

    while b != [0]*len(b):
        if len(b) == 0:
            break
        if len(a) > len(b):
            a, b = b, a

        # Polynomial division
        quotient = [0] * len(b)
        remainder = [0] * len(a)

        for i in range(len(b) - 1, -1, -1):
            if a[i + len(b) - 1] != 0:
                quotient[i] = a[i + len(b) - 1]  # Leading coefficient of a divided by leading coefficient of b
            for j in range(len(b)):
                remainder[i + j] -= quotient[i] * b[j]

        steps += 1
        a = remainder

    if steps == n:
        print(deg1)
        print(' '.join(map(str, f1)))
        print(deg2)
        print(' '.join(map(str, f2)))
    else:
        print(-1)

