def count_ways(n, grid):
    # Find position of the circle
    circle = None
    for i in range(3):
        for j in range(n):
            if grid[i][j] == 'O':
                circle = (i, j)
                break
        if circle:
            break

    # Count non-forbidden cells (excluding the circle)
    non_forbidden = 0
    for i in range(3):
        for j in range(n):
            if grid[i][j] != 'X' and (i, j) != circle:
                non_forbidden += 1

    # We need to cover an odd number of cells with dominoes
    # because each domino covers 2 cells and we need one cell empty
    if non_forbidden % 2 == 0:
        return 0

    # Let's actually implement a correct DP solution

    MOD = 10**9 + 7

    # dp[i] = number of ways to tile columns 1..i
    # with the circle at position (0, i) as empty

    dp = [0] * (n + 1)
    dp[0] = 1
    if n >= 1:
        dp[1] = 1
    if n >= 2:
        for i in range(2, n + 1):
            # dp[i] = dp[i-1] + dp[i-2] + dp[i-3]
            dp[i] = (dp[i-1] + dp[i-2] + dp[i-3]) % MOD

    # The answer is dp[n]
    return dp[n]

# Read input
