    tree = []
    root = 0
    for i in range(n):
        v, l, r = map(int, input().split())
        tree.append((v, l, r))
        if l == -1 and r == -1:
            # This node could be the root
            root = i

    # Find the actual root (the node that has no parent)
    parent = [-1] * n
    for i in range(n):
        v, l, r = tree[i]
        if l != -1:
            parent[l - 1] = i
        if r != -1:
            parent[r - 1] = i

    root = tree.index(-1 in [parent[i] for i in range(n)])  # Actually, find the node with no parent
    for i in range(n):
        if parent[i] == -1:
            root = i
            break

    def search(value):
        node = root
        while node != -1:
            v = tree[node][0]
            if v == value:
                return True
            if value < v:
                node = tree[node][1] - 1  # Go left
            else:
                node = tree[node][2] - 1  # Go right
        return False

    # Count fails
    fails = 0
    values = []
    for i in range(n):
        value = tree[i][0]
        if value not in values:
            # Search from each occurrence
            for j in range(n):
                if tree[j][0] == value:
                    if not search(tree[j][0]):
                        fails += 1
            values.append(value)

