from collections import defaultdict, deque

def main():
    n, m = map(int, input().split())
    edges = []
    adj = defaultdict(list)
    for idx in range(m):
        u, v = map(int, input().split())
        edges.append((u, v))
        adj[u].append(v)
        adj[v].append(u)

    # Function to check if all vertices have even degree
    def even_degree(chosen_edges):
        new_degree = defaultdict(int)
        for k in range(m):
            if k not in chosen_edges:
                u, v = edges[k]
                new_degree[u] += 1
                new_degree[v] += 1

        for v in range(1, n+1):
            if new_degree[v] % 2 != 0:
                return False
        return True

    # Function to check if graph is connected
    def connected(chosen_edges):
        # Build adjacency list without chosen edges
        new_adj = defaultdict(list)
        for k in range(m):
            if k not in chosen_edges:
                u, v = edges[k]
                new_adj[u].append(v)
                new_adj[v].append(u)

        # Find vertices with degree > 0 in the new graph
        non_zero_vertices = [v for v in range(1, n+1) if new_degree[v] > 0]

        if not non_zero_vertices:
            return True  # No edges, trivially connected

        # BFS from starting vertex
        visited = set()
        start = non_zero_vertices[0]
        queue = deque([start])
        visited.add(start)

        while queue:
            u = queue.popleft()
            for v in new_adj[u]:
                if v not in visited:
                    visited.add(v)
                    queue.append(v)

        # Check if all non-zero degree vertices are visited
        return all(v in visited for v in non_zero_vertices)

    # Main algorithm
    count = 0
    for i in range(m):
        for j in range(i + 1, m):
            if even_degree({i, j}) and connected({i, j}):  # Check even degree and connected
                count += 1

    print(count)

if __name__ == "__main__":
    main()
