def find_failures(n, nodes):
    """Count how many times search algorithm will fail on each node's value."""

    # Build the tree
    tree = {}  # node_index -> (value, left_child, right_child)
    parent = {}  # node_index -> parent_index

    for idx in range(1, n + 1):
        v, l, r = nodes[idx]
        tree[idx] = (v, l, r)

        if l != -1:
            parent[l] = idx
        if r != -1:
            parent[r] = idx

    # Find the root (no parent)
    root = None
    for idx in range(1, n + 1):
        if idx not in parent:
            root = idx
            break

    # Set of all node values
    values = set()
    for idx in range(1, n + 1):
        values.add(tree[idx][0])

    # Count failures
    fail_count = 0

    # For each unique value, perform search from every node with that value
    for value in values:
        # Find all nodes with this value
        nodes_with_value = [idx for idx in range(1, n + 1) if tree[idx][0] == value]

        for start_node in nodes_with_value:
            current = start_node
            success = False

            while current != -1:
                val, l, r = tree[current]

                if val == value:
                    success = True
                    break
                elif value < val:
                    current = l
                else:
                    current = r

            if not success:
                fail_count += 1

    return fail_count

