import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    t = int(data[idx])
    idx += 1

    results = []

    for _ in range(t):
        n = int(data[idx])
        idx += 1
        a = list(map(int, data[idx:idx+n]))
        idx += n

        # Sort array in descending order
        a.sort(reverse=True)

        alice_score = 0
        bob_score = 0
        turn = 0  # 0 for Alice, 1 for Bob

        for num in a:
            if turn == 0:
                # Alice's turn: add to score if even
                if num % 2 == 0:
                    alice_score += num
            else:
                # Bob's turn: add to score if odd
                if num % 2 == 1:
                    bob_score += num

            turn = 1 - turn

        if alice_score > bob_score:
            results.append("Alice")
        elif bob_score > alice_score:
            results.append("Bob")
        else:
            results.append("Tie")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
"}

