    import sys
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # DP: dp[i] = set of possible counts of original elements using first i numbers
    dp = [set() for _ in range(n + 1)]
