def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # For each number in Borys's list, find all possible original numbers x
    # and count how many times each x can be used
    x_counts = {}

    for num in a:
        # Find all possible original numbers x that can generate num
        # as a summand in their prairie partition
        k = 0
        while True:
            # Check if num can be the last summand (r) of some prefix
            # with powers 1, 2, 4, ..., 2^{k}
            prev = 1 << (k - 1) if k > 0 else 0
            power_of_2 = 1 << k

            # Case 1: num is exactly the sum of all powers up to 2^k
            if prev + power_of_2 == num:
                x = power_of_2
                x_counts[x] = x_counts.get(x, 0) + 1
            # Case 2: num is the remainder after sum of all powers up to 2^{k-1}
            elif num < prev + power_of_2:
                x = (1 << k) - 1 + num
                x_counts[x] = x_counts.get(x, 0) + 1
            else:
