    # Now find all possible lengths m
    possible_lengths = []

    # For each possible original number x, count how many times it can be used
    for x, count in x_counts.items():
        possible_lengths.append(count)

    if possible_lengths:
        possible_lengths.sort()
        for length in possible_lengths:
            print(length)
    else:
        print(-1)

