def is_beautiful(s, k):
    count = [0] * 26
    for ch in s:
        count[ord(ch) - ord('a')] += 1
    for c in count:
        if c % k != 0:
            return False
    return True

T = int(input())
for _ in range(T):
    n, k = map(int, input().split())
    s = input().strip()

    # Check if s itself is beautiful
    if is_beautiful(s, k):
        print(s)
        continue

    # Try to find the next beautiful string by incrementing from right to left
    chars = list(s)
    found = False
    for i in range(n-1, -1, -1):
        # Try to increment chars[i]
        for ch in range(ord(chars[i]) - ord('a') + 1, 26):
            chars[i] = chr(ch)

            # Calculate the counts for the current configuration
            count = [0] * 26
            for j in range(n):
                count[ord(chars[j]) - ord('a')] += 1

            # Check if we can fill the rest with 'a' to make it beautiful
            valid = True
            for c in count:
                if c % k != 0:
                    valid = False
                    break

            if valid:
                # Fill the rest with 'a' to get the lexicographically smallest string
                chars[i:] = ['a'] * (n - i)
                print(''.join(chars))
                found = True
                break

        if found:
            break

    if not found:
        print(-1)
