import sys
import math

def count_blocks(X):
    """Count the number of blocks for a given X using greedy algorithm"""
    if X == 0:
        return 0

    # Find largest cube <= X
    side = int(X ** (1/3))

    # Check if side^3 is <= X
    while (side + 1) ** 3 <= X:
        side += 1
    while side ** 3 > X:
        side -= 1

    return 1 + count_blocks(X - side ** 3)

def find_optimal(m):
    """Find the optimal X <= m that maximizes number of blocks"""
    max_blocks = 0
    best_X = 0

    # Try all X from 1 to m (this will be too slow for large m)
    for X in range(1, m + 1):
        blocks = count_blocks(X)

        if blocks > max_blocks:
            max_blocks = blocks
            best_X = X
        elif blocks == max_blocks and X > best_X:
            best_X = X

    return max_blocks, best_X

m = int(sys.stdin.readline())
result = find_optimal(m)
print(result[0], result[1])
"}

