# Read input
s = input().strip()

count = [0, 0, 0, 0]  # L, R, U, D
for ch in s:
    if ch == 'L':
        count[0] += 1
    elif ch == 'R':
        count[1] += 1
    elif ch == 'U':
        count[2] += 1
    elif ch == 'D':
        count[3] += 1

total_x = count[0] - count[1]  # L-R
    total_y = count[2] - count[3]  # U-D

total_abs = abs(total_x) + abs(total_y)
if total_abs % 2 != 0:
    print(-1)
else:
    result = max(abs(total_x), abs(total_y))
    print(result)
"}

