import sys

def z_sort(a):
    # Sort the array
    a_sorted = sorted(a)

    # Result array
    result = [0] * len(a)

    # For even positions (0-indexed: 1, 3, 5...), we want larger elements
    # For odd positions (0-indexed: 2, 4, 6...), we want smaller elements

    # Use two pointers: start from the beginning for odd positions, end from the end for even positions
    start = 0
    end = len(a_sorted) - 1

    for i in range(len(a)):
        if i % 2 == 0:  # Even index (0-indexed: 0, 2, 4...)
            result[i] = a_sorted[start]
            start += 1
        else:  # Odd index (0-indexed: 1, 3, 5...)
            result[i] = a_sorted[end]
            end -= 1

    return result

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    result = z_sort(a)

    if n <= 2:
        # Special case: with n <= 2, any arrangement works
        print(' '.join(map(str, a)))
    else:
        # Check if the result is z-sorted
        valid = True
        for i in range(1, n):
            if i % 2 == 0:  # Even index (1-indexed: 2, 4, 6...)
                if result[i] < result[i-1]:
                    valid = False
                    break
            else:  # Odd index (1-indexed: 3, 5, 7...)
                if result[i] > result[i-1]:
                    valid = False
                    break

        if valid:
            print(' '.join(map(str, result)))
        else:
            print("Impossible")

def run():
    main()

if __name__ == "__main__":
    run()
"}

