    # Check if n has at least three distinct prime factors
    # If yes, we can always find three distinct factors >= 2

    # Edge case: n is very small (2 <= n <= 20)
    if n <= 20:
        # Check if n can be expressed as a product of three distinct integers >= 2
        # Brute force check
        for a in range(2, int(n ** (1/3)) + 1):
            for b in range(a + 1, int((n / a) ** (1/2)) + 1):
                if n % (a * b) == 0:
                    c = n // (a * b)
                    if c > b:
                        print(f"YES\n{a} {b} {c}")
                        break
            else:
                continue
            break
        else:
            print("NO")
        continue

    # Check if n has at least three distinct prime factors
    prime_factors = set()

    # Check for factors up to sqrt(n)
    for i in range(2, int(math.isqrt(n)) + 1):
        if n % i == 0:
            prime_factors.add(i)
            if len(prime_factors) >= 3:
                # We have at least three distinct prime factors
                print("YES\n2 3 4")  # Any distinct integers >= 2 will work
                break
            # Also check the corresponding co-factor
            if n % (n // i) == 0:
                prime_factors.add(n // i)
                if len(prime_factors) >= 3:
                    print("YES\n2 3 4")
                    break
    else:
        # No factors found, check if n is prime
        if len(prime_factors) == 1:
            # n is prime
            if n >= 6:
                # n = p, we need three numbers >= 2 that multiply to p
                # Possible: 2, 3, p/6 (but needs to be integer)
                if n % 6 == 0:
                    print(f"YES\n2 3 {n // 6}")
                else:
                    print("NO")
            else:
                print("NO")
        else:
            # n is prime square (p^2)
            print("NO")

