import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Initialize grid
    grid = [[False for _ in range(n + 1)] for _ in range(n + 1)]  # 1-indexed

    # Track which cells have been painted and at what move
    move_to_cells = []

    for move in range(1, m + 1):
        x = int(next(it))
        y = int(next(it))

        grid[x][y] = True
        move_to_cells.append((x, y))

    # Check after each move if any 3x3 square is fully painted
    result = -1

    for move in range(1, m + 1):
        # Get all cells painted at this move
        cells = move_to_cells[move - 1]

        # Check all possible 3x3 squares
        found = False

        for i in range(1, n - 2 + 1):
            for j in range(1, n - 2 + 1):
                # Check if all 9 cells in this 3x3 square are painted
                all_painted = True

                for dx in range(3):
                    for dy in range(3):
                        cell = (i + dx, j + dy)
                        if not grid[cell[0]][cell[1]]:
                            all_painted = False
                            break
                    if not all_painted:
                        break

                if all_painted:
                    result = move
                    found = True
                    break
            if found:
                break

        if result != -1:
            break

    print(result)

if __name__ == "__main__":
    main()
