def sum_of_digits(x):
    """Calculate the sum of digits of a number x."""
    return sum(int(digit) for digit in str(x))

def solve():
    n = int(input())

    # Try all possible values of s(x) (max sum of digits)
    # For a number up to 10^18, max sum of digits is 9 * 18 = 162
    max_sum = 200  # A bit larger for safety

    for s in range(1, max_sum + 1):
        # Solve quadratic equation: x^2 + s*x - n = 0
        discriminant = s*s + 4*n
        sqrt_d = int(discriminant**0.5)

        if sqrt_d * sqrt_d != discriminant:
            continue

        x = (sqrt_d - s) // 2

        if n % (x * x) == 0 and sum_of_digits(x) == s:
            # Check if x satisfies the equation
            if x * x + s * x == n:
                print(x)
                return

    print(-1)

solve()
