    t = parts[0]
    k = int(parts[1])
    positions = list(map(int, parts[2:2+k]))

    for pos in positions:
        for i, ch in enumerate(t):
            if pos + i not in constraints:
                constraints[pos + i] = []
            constraints[pos + i].append(ch)

