    if pos in constraints:
        cnt = {}
        for ch in constraints[pos]:
            cnt[ch] = cnt.get(ch, 0) + 1
        most_common = max(cnt.items(), key=lambda x: x[1])[0]
        result.append(most_common)
    else:
        result.append('a')

print(''.join(result))
