def solve():
    n = int(input())

    # Dictionary to store required characters at each position
    required = {}

    for _ in range(n):
        parts = input().split()
        ti = parts[0]
        ki = int(parts[1])
        positions = list(map(int, parts[2:2+ki]))

        # Calculate the maximum length needed
        max_len = max(max_len, positions[-1] + len(ti) - 1)

        # Store required characters
        for pos in positions:
            for i in range(len(ti)):
                required[pos + i] = ti[i]

    # Build the result string
    result = [''] * max_len
    for pos in range(1, max_len + 1):
        if pos in required:
            result[pos - 1] = required[pos]
        else:
            # Fill with 'a' to get lexicographically minimal
            result[pos - 1] = 'a'

    print(''.join(result))

if __name__ == "__main__":
    solve()
