def solve():
    n = int(input())
    tree = {}  # node index -> (value, left, right)
    nodes = []  # list of nodes by index (0-indexed? Let's assume they're 1-indexed as per input)
    for i in range(n):
        v, l, r = map(int, input().split())
        tree[i + 1] = (v, l, r)
        nodes.append((v, l, r))

    # For each node, simulate the search algorithm from root (which is index 1?)
    # Wait, we need to determine which node is the root. The root is the node that is not a child of any other node.
    # Let's find the root by checking which node is not a child.

    children = set()
    for v, l, r in nodes:
        if l != -1:
            children.add(l)
        if r != -1:
            children.add(r)

    # Find which node is the root (not a child of anyone)
    for i in range(1, n + 1):
        if i not in children:
            root_index = i
            break

    # Now run the search algorithm for each value in the tree
    failures = 0
    for i in range(1, n + 1):
        # Simulate search for value of node i
        current = root_index
        found = False
        while current != -1:
            value, left, right = tree[current]
            if value == nodes[i - 1][0]:  # nodes[i-1] is the value of node i
                found = True
                break
            elif nodes[i - 1][0] < value:
                current = left
            else:
                current = right
        if not found:
            failures += 1

    print(failures)

