import sys

def solve():
    n = int(sys.stdin.readline())
    events = []
    for _ in range(2 * n):
        line = sys.stdin.readline().strip()
        if line[0] == '+':
            events.append(('+', 0))
        else:
            x = int(line.split()[1])
            events.append(('-', x))

    # Work backwards
    available = set(range(1, n + 1))
    order = []

    for event in reversed(events):
        if event[0] == '+':
            # In reverse, a placement means we remove a shuriken from available
            # We should remove the cheapest available shuriken (since in forward time,
            # the last placement would be the cheapest at that moment)
            if available:
                cheapest = min(available)
                available.remove(cheapest)
                order.append(cheapest)
            else:
                return "NO"
        else:
            # In reverse, a removal means we add back the shuriken
            x = event[1]
            available.add(x)

    if available:
        return "NO"

    return "YES\n" + " ".join(map(str, order))

result = solve()
if result:
    sys.stdout.write(result)
else:
    sys.stdout.write("NO")
