def is_win(board, player):
    # Check rows
    for i in range(3):
        if board[i][0] == board[i][1] == board[i][2] == player:
            return True

    # Check columns
    for j in range(3):
        if board[0][j] == board[1][j] == board[2][j] == player:
            return True

    # Check diagonals
    if board[0][0] == board[1][1] == board[2][2] == player:
        return True
    if board[0][2] == board[1][1] == board[2][0] == player:
        return True

    return False

# Read board
board = []
for _ in range(3):
    line = input().strip()
    board.append(list(line))

# Count X and 0
x_count = sum(row.count('X') for row in board)
zero_count = sum(row.count('0') for row in board)

# Check if board is illegal
if x_count > zero_count + 1 or zero_count > x_count:
    print("illegal")
else:
    # Check if X has already won
    if is_win(board, 'X'):
        if x_count == zero_count + 1:
            print("draw")  # X just won, game over, it's a draw
        else:
            print("illegal")  # Invalid winning condition

    # Check if 0 has already won
    elif is_win(board, '0'):
        if zero_count == x_count:
            print("draw")  # 0 just won, game over, it's a draw
        else:
            print("illegal")  # Invalid winning condition

    # Check if the game ended in a draw
    elif x_count + zero_count == 9:
        print("draw")  # Board full, no winner

    # Determine whose turn is next
    else:
        if x_count == zero_count:
            print("first")  # X's turn (first player)
        else:
            print("second")  # 0's turn (second player)
