def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def get_primes_less_than(n):
    return [i for i in range(2, n) if is_prime(i)]

def get_next_number(current, prime):
    """Get the next number after a move using a prime."""
    if current % prime == 0:
        return current
    return current + (prime - current % prime)

def get_previous_numbers(target, prime):
    """Get all numbers that could lead to target using this prime."""
    prev_numbers = []
    # Try all numbers less than target
    for num in range(1, target):
        if get_next_number(num, prime) == target:
            prev_numbers.append(num)
    return prev_numbers

def solve(X2):
    """Find the minimum possible starting number X0."""
    # Step 1: Find all primes < X2 that could lead to X2
    primes = get_primes_less_than(X2)

    # Step 2: For each prime, find all possible X1 values
    possible_X1 = set()
    for prime in primes:
        # For a prime p, any X1 that is a multiple of p will stay the same
        # So if X2 is a multiple of p, then X1 could be X2 (but X1 < X2)
        if X2 % prime == 0:
            possible_X1.add(X2)

        # For any X1 that is not a multiple of p, we need:
        # get_next_number(X1, prime) = X2
        # => X1 + (prime - X1 % prime) = X2
        # => X1 = X2 - (prime - X1 % prime)
        # This is complex, let me think differently

        # Try all numbers less than X2 to see which ones could lead to X2
        for num in range(1, X2):
            if get_next_number(num, prime) == X2:
                possible_X1.add(num)
                break

    # Step 3: For each possible X1, find all possible X0 values
    possible_X0 = set()
    for X1 in possible_X1:
        # Now find all primes < X1 that could lead to X1
        primes_for_X1 = get_primes_less_than(X1)

        # For each prime, find all numbers that could lead to X1
        for prime in primes_for_X1:
            for num in range(1, X1):
                if get_next_number(num, prime) == X1:
                    possible_X0.add(num)
                    break

    # Step 4: Return the minimum X0
    return min(possible_X0) if possible_X0 else None

