            # Street goes east to west
            if vertical[j] == '^':
                # Can go west to (i, j-1) if vertical street j-1 is north to south
                adj[(i, j)].append((i, j-1))

        # Check vertical directions
        if vertical[j] == '^':
            # Street goes north to south
            if horizontal[i] == '>':
                # Can go south to (i+1, j) if horizontal street i is west to east
                adj[(i, j)].append((i+1, j))
        elif vertical[j] == 'v':
            # Street goes south to north
            if horizontal[i] == '<':
                # Can go north to (i-1, j) if horizontal street i-1 is east to west
                adj[(i, j)].append((i-1, j))

