    for i in range(1, n + 1):
        if i not in closed:
            remaining.append(tabs[i-1])

    e = sum(1 for t in remaining if t == 1)
    s = sum(1 for t in remaining if t == -1)
    diff = abs(e - s)

    max_diff = max(max_diff, diff)

