tabs = list(map(int, input().split()))

max_diff = 0

# Try each possible starting point b
for b in range(1, n + 1):
    # Find all tabs that will be closed
    closed = set()
    # Check all possible i (positive and negative)
    i = 1
    while True:
        c = b + i * k
        if 1 <= c <= n:
            closed.add(c)
            i += 1
        else:
            break

    i = 1
    while True:
        c = b - i * k
        if 1 <= c <= n:
            closed.add(c)
            i += 1
        else:
            break

    # Count remaining tabs
    e = 0
    s = 0
    for i in range(1, n + 1):
        if i not in closed:
            if tabs[i-1] == 1:
                e += 1
            else:
                s += 1

    diff = abs(e - s)

    max_diff = max(max_diff, diff)

print(max_diff)
