def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        evens = []
        odds = []
        for num in a:
            if num % 2 == 0:
                evens.append(num)
            else:
                odds.append(num)

        count_evens = len(evens)
        count_odds = len(odds)

        # Determine how many numbers Alice takes
        if count_evens > count_odds:
            # Alice takes all odds + 1 even
            alice_take = count_odds + 1
        else:
            # Alice takes all evens
            alice_take = count_evens

        # Alice gets the largest alice_take even numbers
        alice_score = sum(sorted(evens, reverse=True)[:alice_take])

        # Bob gets the remaining odds (count_odds - (alice_take - 1))
        bob_score = sum(sorted(odds, reverse=True)[:count_odds - (alice_take - 1)])

        if alice_score > bob_score:
            print("Alice")
        elif bob_score > alice_score:
            print("Bob")
        else:
            print("Tie")

solve()
"}

