import sys

def solve():
    q = int(sys.stdin.readline())
    for _ in range(q):
        b, w = map(int, sys.stdin.readline().split())
        total = b + w

        if total % 2 == 0:
            if b != w:
                print("NO")
            else:
                # Output YES and the component
                print("YES")
                # Let's output a rectangle of size b x 1 (or 1 x b)
                for i in range(b):
                    print(1 + i, 1)
        else:
            if abs(b - w) != 1:
                print("NO")
            else:
                # Output YES and the component
                print("YES")
                # For simplicity, let's output a vertical line of length total (total cells)
                # Start at (1, 1) and go down
                for i in range(total):
                    print(1 + i, 1)

if __name__ == "__main__":
    solve()
