    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Track: for each vertex, (regular edges, loops)
    degree = [[] for _ in range(n + 1)]  # index 0 unused

    for _ in range(m):
        u = int(next(it))
        v = int(next(it))

        if u == v:
            # loop
            degree[u].append(0)  # marker for loop
        else:
            # regular edge
            degree[u].append(1)


    total = 0

    for v in range(1, n + 1):
        regular = 0
        loops = 0

        for val in degree[v]:
            if val == 0:
                loops += 1
            else:
                regular += 1

        # C(regular, 2) = regular * (regular - 1) // 2
        # regular * loops
        total += regular * (regular - 1) // 2 + regular * loops

    print(total)

