import math

def solve():
    n, a, d = map(int, input().split())
    results = []

    for i in range(n):
        ti, vi = map(int, input().split())

        # Calculate free arrival time (without considering collisions)
        time_to_max_speed = vi / a
        distance_to_max_speed = 0.5 * a * time_to_max_speed**2

        if distance_to_max_speed >= d:
            # Arrives while still accelerating
            time_to_arrive = math.sqrt(2 * d / a)
        else:
            # Reaches max speed, then continues at that speed
            time_to_arrive = time_to_max_speed + (d - distance_to_max_speed) / vi

        # Check if we catch up with the previous trolleybus
        if i > 0:
            prev_arrival = results[i-1]

            # If we catch up, we arrive at the same time as the previous one
            # Actually, we should check if we arrive before the previous one has departed
            if ti + time_to_arrive < prev_arrival:
                # We catch up with the previous one
                results.append(prev_arrival)
            else:
                # We don't catch up, we arrive at our free arrival time
                results.append(max(ti + time_to_arrive, prev_arrival))
        else:
            results.append(ti + time_to_arrive)

    for result in results:
        print(f"{result:.10f}")

