def solve():
    n = int(input())
    l = list(map(int, input().split()))
    r = list(map(int, input().split()))

    # Check trivial cases
    if l[0] != 0 or r[-1] != 0:
        print("NO")
        return

    # Check if any child claims more children than exist
    for i in range(n):
        if l[i] + r[i] > n - 1:
            print("NO")
            return

    # Try to construct the array using brute force for small n
    if n <= 100:
        # Try all possible permutations of values from 1 to n
        from itertools import permutations
        for values in permutations(range(1, n + 1), n):
            a = values
            # Check if this distribution matches the constraints
            valid = True
            for i in range(n):
                left_count = sum(1 for j in range(i) if a[j] > a[i])
                right_count = sum(1 for j in range(i + 1, n) if a[j] > a[i])
                if left_count != l[i] or right_count != r[i]:
                    valid = False
                    break
            if valid:
                print("YES")
                print(" ".join(map(str, a)))
                return
    else:
        # For larger n, use the greedy approach
        a = [1] * n

        # Process from left to right
        for i in range(n):
            # Count how many children to the left have value > a[i]
            left_count = sum(1 for j in range(i) if a[j] > a[i])

            # We need to satisfy l[i]
            if left_count < l[i]:
                # Need more children with value > a[i] to the left
                # Let's increase a[i] until we get enough
                while left_count < l[i]:
