import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))

    # Track which shurikens are currently on display
    displayed = set()

    # For tracking order of placement
    order = []

    # Read all operations first
    for _ in range(2 * n):
        token = next(it)

        if token[0] == '-':
            # This is a removal operation
            price_part = token[2:]
            if price_part:
                x = int(price_part)
            else:
                x = -1  # invalid format
        else:
            # This is a placement operation
            x = -1

        if token == '+':
            # Place the smallest remaining shuriken
            available = [s for s in range(1, n + 1) if s not in displayed]
            if available:
                shuriken = min(available)
                order.append(shuriken)
                displayed.add(shuriken)
        else:
            # Remove shuriken of price x
            if x not in displayed:
                print("NO")
                return

            if x != min(displayed):
                print("NO")
                return

            displayed.remove(x)

    print("YES")
    print(' '.join(map(str, order)))

if __name__ == "__main__":
    solve()
