def max_divisible_by_three(s):
    n = len(s)
    prefix_sums = [0] * (n + 1)

    # Compute prefix sums (mod 3)
    for i in range(n):
        prefix_sums[i+1] = (prefix_sums[i] + int(s[i])) % 3

    count = 0

    # Find how many times we can split
    for i in range(1, n+1):
        if prefix_sums[i] == 0:
            count += 1

    return count

s = input().strip()
