import sys

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, x, y):
        fx = self.find(x)
        fy = self.find(y)
        if fx == fy:
            return
        if self.size[fx] < self.size[fy]:
            fx, fy = fy, fx
        self.parent[fy] = fx
        self.size[fx] += self.size[fy]


def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    edges = []
    for _ in range(n - 1):
        u = int(next(it)) - 1  # 0-indexed
        v = int(next(it)) - 1
        w = int(next(it))
        edges.append((w, u, v))

    queries = []
    for i in range(m):
        q = int(next(it))
        queries.append((q, i))

    # Sort edges by weight
    edges.sort()

    # Sort queries by threshold
    queries.sort()

    uf = UnionFind(n)
    ans = [0] * m
    count = 0

    for q, idx in queries:
        # Add all edges with weight ≤ q
        for w, u, v in edges:
            if w <= q:
                count += uf.size[uf.find(u)] * uf.size[uf.find(v)]
                uf.union(u, v)
            else:
                break

        ans[idx] = count

    for a in ans:
        print(a)

if __name__ == "__main__":
    solve()
