import sys

def solve():
    input = sys.stdin.read()
    data = input.split()

    idx = 0
    t = int(data[idx])
    idx += 1

    results = []

    for _ in range(t):
        n = int(data[idx])
        W = int(data[idx + 1])
        idx += 2

        weights = list(map(int, data[idx:idx + n]))
        idx += n

        # Check if any item is >= W
        for i in range(n):
            if weights[i] >= W:
                results.append(str(1))
                results.append(str(i + 1))
                break
        else:
            # Check if any item is >= ceil(W/2)
            half = (W + 1) // 2
            for i in range(n):
                if weights[i] >= half:
                    results.append(str(1))
                    results.append(str(i + 1))
                    break
            else:
                # Sort items in descending order
                items = sorted([(i + 1, weights[i]) for i in range(n)], key=lambda x: x[1], reverse=True)

                selected = []
                total = 0

                for item in items:
                    if total >= W:
                        break
                    if total + item[1] <= W:
                        selected.append(item[0])
                        total += item[1]
                    elif total + item[1] >= half:
                        # We can take this item alone
                        selected.append(item[0])
                        break

                if len(selected) == 0 or total < half:
                    results.append("-1")
                else:
                    results.append(str(len(selected)))
                    results.append(" ".join(map(str, selected)))

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
