# Count X and 0
count_x = sum(row.count('X') for row in board)
count_0 = sum(row.count('0') for row in board)  # Note: '0' is a digit zero

# Check if X has won
x_won = is_winning(board, 'X')
# Check if 0 has won
zero_won = is_winning(board, '0')

# Check if both players have won (illegal)
if x_won and zero_won:
    print("illegal")
else:
    # Check if someone won and the move counts are valid
