# Function to compute final sequence for n
def compute_final_sequence(n):
    if n == 0:
        return [0]
    if n == 1:
        return [1]
    seq = [n]

    # While the sequence contains elements > 1
    while True:
        i = 0
        changed = False
        while i < len(seq):
            if seq[i] > 1:
                # Remove x and insert [x-1, 1]
                x = seq[i]
                seq.pop(i)
                seq.insert(i, x - 1)
                seq.insert(i, 1)
                changed = True
                # Reset i to start processing from the beginning
                i = 0
            else:
                i += 1
        if not changed:
            break
    return seq

final = compute_final_sequence(n)

# Count 1s in range l to r
ones = 0
for i in range(l - 1, r):
    if i < len(final) and final[i] == 1:
        ones += 1

print(ones)
