import sys
from collections import deque

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    horizontal = data[2]
    vertical = data[3]

    # Build adjacency list
    adj = {}  # (i, j) -> list of reachable nodes

    for i in range(n):
        for j in range(m):
            adj[(i, j)] = []

            # Horizontal movement
            if horizontal[i] == '<':  # east to west (left to right)
                if j > 0:
                    adj[(i, j)].append((i, j - 1))
            elif horizontal[i] == '>':  # west to east (right to left)
                if j < m - 1:
                    adj[(i, j)].append((i, j + 1))

            # Vertical movement
            if vertical[j] == '^':  # south to north (bottom to top)
                if i > 0:
                    adj[(i, j)].append((i - 1, j))
            elif vertical[j] == 'v':  # north to south (top to bottom)
                if i < n - 1:
                    adj[(i, j)].append((i + 1, j))

    # Check if the graph is strongly connected
    if not adj:
        print("YES")
        return

    # Pick any starting node
    start = next(iter(adj))

    # BFS to find all reachable nodes from start
    reachable = set()
    queue = deque([start])
    reachable.add(start)

    while queue:
        node = queue.popleft()
        for neighbor in adj[node]:
            if neighbor not in reachable:
                reachable.add(neighbor)
                queue.append(neighbor)

    # Check if all nodes are reachable
    if len(reachable) == len(adj):
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    solve()
